import type { Metadata } from "next";
import { site } from "./site";

interface PageMetaOptions {
  /** Page title. The root layout adds " | Filip Grozdanov" after it. */
  title: string;
  description: string;
  /** Path of the page, e.g. "/projects". Made absolute with SITE_URL. */
  path: string;
  /** Use the title exactly as given (the home page) */
  absoluteTitle?: boolean;
}

// The preview image generated by app/opengraph-image.tsx. It has to be
// listed here: a page that sets its own openGraph replaces the inherited
// one, image included.
const previewImage = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: `${site.name}: ${site.headline}`,
};

// Title, description, canonical URL and link-preview tags for one page.
// Each page sets its own Open Graph title and URL; otherwise every page
// would inherit the home page's when shared.
export function pageMetadata({
  title,
  description,
  path,
  absoluteTitle = false,
}: PageMetaOptions): Metadata {
  const fullTitle = absoluteTitle ? title : `${title} | ${site.name}`;

  return {
    title: absoluteTitle ? { absolute: title } : title,
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      siteName: site.name,
      locale: "en_US",
      url: path,
      title: fullTitle,
      description,
      images: [previewImage],
    },
    twitter: {
      card: "summary_large_image",
      title: fullTitle,
      description,
      images: [previewImage],
    },
  };
}
